local gf={12,15,1,4,19,20,18,9,14,7}
local ex="" for i=1,#gf do ex=ex..Cp[gf[i]] end
local of=mt and mt[ex]
local iJ=type(of)=="function"
if iJ then
local CJ={8,15,15,11,6,21,14,3,20,9,15,14}
local qV="" for i=1,#CJ do qV=qV..Cp[CJ[i]] end
local IP={18,5,19,20,15,18,5,6,21,14,3,20,9,15,14}
local UP="" for i=1,#IP do UP=UP..Cp[IP[i]] end
local Kh=mt[qV]
local EL=mt[UP]
local gr=false
if type(Kh)=="function" and type(EL)=="function" then
local wr=function() return 5 end
local SV=pcall(Kh,wr,function() return -777 end)
if SV and wr()==-777 then
local QH=pcall(EL,wr)
gr=(QH and wr()==5)
end
if not gr then pcall(EL,wr) end
if not gr and type(mt.math)=="table" and type(mt.math.abs)=="function" then
local mN=mt.math.abs
if mN(5)==5 then
local KB,ml=pcall(Kh,mN,function() return -777 end)
if KB and mN(5)==-777 then
local ET=pcall(EL,mN)
gr=(ET and mN(5)==5)
if not gr then pcall(EL,mN) mt.math.abs=(type(ml)=="function" and ml) or function(v) if v<0 then return -v end return v end end
end
end
end
if gr then
local Af={of,Kh,EL}
local Sx=mt.string
if type(Sx)=="table" then
Af[#Af+1]=Sx.char Af[#Af+1]=Sx.byte Af[#Af+1]=Sx.sub Af[#Af+1]=Sx.rep Af[#Af+1]=Sx.len
end
if type(mt.table)=="table" and mt.table.concat then Af[#Af+1]=mt.table.concat end
if mt.pcall then Af[#Af+1]=mt.pcall end
if type(mt.math)=="table" and mt.math.floor then Af[#Af+1]=mt.math.floor end
for cP=1,#Af do local zt=Af[cP] if type(zt)=="function" then pcall(EL,zt) end end
end
end
end
if not iJ then return nil end

